-- Daftar ruang rapat pindah dari konstanta kode (ROOMS) ke tabel ruang_profil: satu baris = satu ruangan
-- yang bisa dibooking. Admin/Kabag bisa menambah/mengubah/menghapus ruangan di menu "Foto & Fasilitas Ruang".
-- Ruangan dikelompokkan per satuan kerja (bagian) di jadwal, kiosk, dan form booking.
ALTER TABLE "ruang_profil"
  ADD COLUMN "satuan_kerja" VARCHAR(150) NOT NULL DEFAULT '',
  ADD COLUMN "kapasitas"    INTEGER,
  ADD COLUMN "link_foto"    VARCHAR(500),
  ADD COLUMN "sort_order"   INTEGER NOT NULL DEFAULT 0;
CREATE INDEX "ruang_profil_sort_order_idx" ON "ruang_profil"("sort_order");

-- Isi awal dari spreadsheet "DATA RUANG RAPAT DI SEKRETARIAT JENDERAL KEMENTERIAN KETENAGAKERJAAN".
-- Kunci ruangan lama (SERBAGUNA, SETJEN II, TRI DHARMA, BIRO UMUM, GRAHA KEMNAKER) dipertahankan karena
-- sudah dipakai di data booking & foto. Fasilitas mengikuti spreadsheet (kecuali spreadsheet kosong).

ON CONFLICT ("room") DO UPDATE SET
  "satuan_kerja" = EXCLUDED."satuan_kerja",
  "kapasitas"    = EXCLUDED."kapasitas",
  "link_foto"    = EXCLUDED."link_foto",
  "sort_order"   = EXCLUDED."sort_order",
  "fasilitas"    = CASE WHEN EXCLUDED."fasilitas" = '[]'::jsonb THEN "ruang_profil"."fasilitas" ELSE EXCLUDED."fasilitas" END;
